 for(const [x,z,y,w,d] of [[-90,57,1,78,65],[-82,-15,7,62,65],[-68,-64,17,62,56],[111,-63,25,64,67],[139,14,8,50,88],[-118,-107,27,100,65],[12,-145,34,120,70],[110,-145,35,100,67]]){box(x,y-30,z,w,60,d,'rock');for(let i=0;i<18;i++){const a=i/18*Math.PI*2;inst('rock','rock',x+Math.cos(a)*w*.47,y-16,z+Math.sin(a)*d*.47,4+rnd()*5,16+rnd()*12,4+rnd()*5,0,rnd()*6);}}
 box(20,-20.5,5,200,.6,210,'water');
 for(let i=0;i<24;i++){const x=-145+rnd()*300,z=-178+rnd()*35,h=12+rnd()*38;building(x,z,30,5+rnd()*5,7,h);}
 for(const f of L.FLOORS){box(f.x,f.height-.7,f.z,f.w,1.4,f.d,'road');for(let x=f.x1+2;x<f.x2;x+=4)box(x,f.height+.012,f.z,.035,.022,f.d-.2,'dark');for(let z=f.z1+2;z<f.z2;z+=4)box(f.x,f.height+.013,z,f.w-.2,.025,.035,'dark');}
 for(let i=0;i<L.ROUTE.length-1;i++){const a=L.ROUTE[i],b=L.ROUTE[i+1],dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz),rx=dz/len*2.9,rz=-dx/len*2.9;
  const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute([a[0]+rx,a[1]+.025,a[2]+rz,a[0]-rx,a[1]+.025,a[2]-rz,b[0]+rx,b[1]+.025,b[2]+rz,b[0]-rx,b[1]+.025,b[2]-rz],3));g.setIndex([0,2,1,1,2,3]);g.computeVertexNormals();const mat=mats.road.clone();mat.side=T.DoubleSide;mesh(g,mat,0,0,0);beam([a[0],a[1]+.045,a[2]],[b[0],b[1]+.045,b[2]],.055,'pink');for(const s of [-1,1]){const p=[a[0]+s*rx,a[1],a[2]+s*rz],q=[b[0]+s*rx,b[1],b[2]+s*rz];beam(p,q,.28,'steel');if(Math.abs(a[1]-b[1])>.1)rail(p,q);}
 }
