 for(const [x,z,y] of L.COVER){box(x,y+.47,z,2.6,.94,.8,'concrete');box(x,y+.95,z,2.6,.13,.83,'steel');box(x,y+.62,z+.42,2.2,.16,.04,'gold');crate(x+2,z,y);}
 for(const [x,z,y] of [[-94,43,2],[-77,42,2],[-79,19,8],[-65,7,8],[-55,-1,12],[-39,-39,25],[0,-53,25],[25,-53,25],[50,-53,25],[75,-53,25],[100,-53,25]])lamp(x,z,y);
 for(const [x,z,y] of [[-109,37,2],[-109,28,2],[-99,11,8],[-85,-26,8],[-92,-19,8],[-65,-52,19],[-73,-45,19],[128,-48,31],[125,-78,31],[-91,18,8],[-56,30,8],[-84,24,8]])for(let i=0;i<3;i++)tree(x+(rnd()-.5)*3,z+(rnd()-.5)*3,y);
 // Evacuation tents, field equipment and shelters.
 for(const [x,z] of [[-78,16],[-78,25],[-59,13]]){for(const dx of [-2,2])for(const dz of [-2,2])beam([x+dx,8,z+dz],[x+dx,10.6,z+dz],.12);for(const s of [-1,1]){box(x+s*1.05,10.95,z,2.3,.12,4.3,'white',0);box(x+s*.9,8.7,z,1.1,.16,2.1,'white');}box(x,10.7,z+2.15,1.2,.2,.08,'red');box(x,10.7,z+2.2,.2,.8,.08,'red');}
 // Dam spillways: animated texture across actual inclined geometry.
 box(41,4,-46,128,42,14,'concrete');for(const x of [-20,3,26,49,72,95,104]){box(x,4,-38,4,42,4,'dark');box(x,23.8,-34.5,1.9,.35,.4,'warm');}
 const wc=document.createElement('canvas');wc.width=128;wc.height=256;const ctx=wc.getContext('2d');ctx.fillStyle='#4f869e';ctx.fillRect(0,0,128,256);for(let i=0;i<180;i++){ctx.fillStyle='rgba(220,247,255,'+(.1+rnd()*.45)+')';ctx.fillRect(rnd()*128,rnd()*256,1+rnd()*4,12+rnd()*75);}const wt=new T.CanvasTexture(wc);wt.wrapS=wt.wrapT=T.RepeatWrapping;wt.repeat.set(2,3);wt.colorSpace=T.SRGBColorSpace;textures.push(wt);
 for(const x of [14,46,78]){box(x,15,-38.9,14,13,.6,'dark');box(x,19,-38.5,14,1,.35,'red');for(let j=0;j<8;j++)box(x-6+j*1.7,15,-38.45,.14,9,.32,'steel');const g=new T.PlaneGeometry(13,34,4,12);const p=g.attributes.position;for(let j=0;j<p.count;j++){const t=(17-p.getY(j))/34;p.setZ(j,9*t*t);}g.computeVertexNormals();const m=new T.MeshStandardMaterial({map:wt,color:0xb0dce8,roughness:.32,side:T.DoubleSide});falls.push(mesh(g,m,x,-4,-38));}
 rail([-22,25,-34],[105,25,-34]);rail([-22,25,-56],[105,25,-56]);sign('ORDRE',-9,9,-38.87,9,3);sign('ORDRE',98,9,-38.87,9,3);
 for(const [i,x] of L.RELAYS.entries()){const id='relais-'+'abc'[i];box(x,25.5,-51,7,1,7,'steel');cyl(x,28.5,-51,2.4,5,'dark');const core=mesh(new T.CylinderGeometry(1.7,1.7,5.2,12),mats.pink.clone(),x,29,-51);relays.set(id,core);for(const y of [26.8,31.6])cyl(x,y,-51,2.75,.5);for(let j=0;j<4;j++){const a=j*Math.PI/2;beam([x+2.3*Math.cos(a),26.5,-51+2.3*Math.sin(a)],[x+2.3*Math.cos(a),32,-51+2.3*Math.sin(a)],.32);}sign('RELAIS '+'ABC'[i],x,33,-48.65,3.6,1.1);}
 for(const x of [45,48,51]){cyl(x,26,-38,.7,1.8);const v=mesh(new T.TorusGeometry(.65,.09,8,24),mats.red,x,27,-38);v.rotation.x=Math.PI/2;doors.set(x,v);}
 sign('VANNES · CONTRÔLE',50,28,-45.85,6,1.1,'#64d5ff');
 // VTOL / extraction.
 cyl(109,32.07,-70,11,.12,'dark');const ring=mesh(new T.TorusGeometry(9.4,.08,8,64),mats.pink,109,32.18,-70);ring.rotation.x=-Math.PI/2;
 for(const s of [-1,1])box(109+s*1.8,32.18,-70,.45,.05,5,'white');box(109,32.18,-70,3.6,.05,.45,'white');
 inst('rock','steel',109,34,-71,1.5,1.05,4.5);inst('rock','glass',109,34.45,-68.8,1.15,.65,1.6);box(109,34,-72,11,.3,2,'dark');for(const s of [-1,1]){box(109+s*4.8,34.1,-72,1.5,.8,3.2,'steel');cyl(109+s*4.8,34.6,-72,1.35,.25,'dark');cyl(109+s*4.8,34.75,-72,.9,.12,'blue');beam([109+s*1.15,32.35,-73],[109+s*1.15,32.35,-69],.18);}
 sign('AEGIS · EXTRACTION',109,30,-55.9,8,1.3,'#c7e9ff');
 for(const it of L.INTERACTIONS){const r=mesh(new T.TorusGeometry(.46,.03,6,24),mats.blue.clone(),it.x,it.y+.06,it.z);r.rotation.x=-Math.PI/2;markers.set(it.id,{r,done:false,active:false});}
 let batchCount=0;for(const [key,list] of instances){const [g,m]=key.split('|'),o=new T.InstancedMesh(geos[g],mats[m],list.length);list.forEach((matrix,i)=>o.setMatrixAt(i,matrix));o.instanceMatrix.needsUpdate=true;o.computeBoundingSphere();o.castShadow=!low&&m!=='leaf';o.receiveShadow=true;root.add(o);batchCount++;}
 let npc=null,buddySphere=null;
 const ready=(async()=>{try{const {installPinkWarsSoldier}=await import('./level2-player.js'),{poseUnarmedForInspection}=await import('./rlh-firefighter.js'),{createGlove}=await import('./hands.js');const id=characterId==='ghju'?'lylu':'ghju';const rig=await installPinkWarsSoldier(T,scene,id);await rig.model.shadowUnit.gear.ready;await rig.model.shadowUnit.suit.ready;const model=rig.model;model.root.position.set(-91,2,57);model.root.visible=true;model.setLevel((await import('./nano-forge.js')).readNanoProfile(id).equippedSuit);const gloves=[createGlove(rig.kit.gloves,{mirror:true,sleeve:false,arm:false}),createGlove(rig.kit.gloves,{sleeve:false,arm:false})];model.root.add(...gloves);poseUnarmedForInspection(model,gloves);npc={...rig,id};const{createCompanionModel}=await import('./companion-model.js');const group=new T.Group();scene.add(group);buddySphere={root:group,model:createCompanionModel(T,group,id==='ghju')};}catch(e){console.warn('M11 / second héros optionnel',e);}return {source:'V2 metric adaptation',batchCount};})();
 function markDone(id,value=true){const p=markers.get(id);if(p){p.done=value;p.r.material.color.setHex(value?0x73edab:p.active?0x46c9ff:0x46505a);}const c=relays.get(id);if(c)c.material.color.setHex(value?0x73edab:0xff2695);}
 let elapsed=0;return {root,sun,ready,build(){},setDoor(){},setLine(){},adapt(){},openPortal(){},markDone,setAvailable(ids){for(const [id,p] of markers){p.active=ids.includes(id);markDone(id,p.done);}},update(t,dt,camera,player){elapsed=t;wt.offset.y=-t*.55;for(const v of doors.values())if(markers.get('vannes')?.done)v.rotation.z+=dt*.3;if(npc&&player){const it=L.INTERACTIONS.find(i=>markers.get(i.id)?.active)||L.INTERACTIONS[0];const x=it.x-2,z=it.z+1;const h=L.createTraversal().height(x,z);npc.model.root.position.set(x,h,z);npc.model.root.visible=h>-40; npc.model.root.lookAt(player.x,h,player.z);if(buddySphere){buddySphere.root.position.set(x+.9,h+1.8+Math.sin(t*1.6)*.1,z);buddySphere.root.visible=npc.model.root.visible;buddySphere.model.update(dt,{pulse:0});}}},stats:()=>({source:'V2 metric native adaptation',batchCount,instances:[...instances.values()].reduce((n,a)=>n+a.length,0),relays:relays.size,secondHero:npc?.id||null,waterfalls:falls.length}),dispose(){npc?.dispose();buddySphere?.model.dispose();buddySphere?.root.removeFromParent();root.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});for(const t of textures)t.dispose();root.removeFromParent();sun.removeFromParent();}};
